// Evidence-backed request-path tests for the Authorizations leaf (Phase 3.1).
//
// Generated by scripts/research/gen-31-tests.py from the rows in api.md, which in turn come from
// docs/research/apk-endpoints.md. Each test calls the method and inspects the URL that actually
// reaches `fetch`, so a rename or a route regression fails here rather than in production.

import BandlabSDK from 'bandlabx';

function makeClient(): BandlabSDK {
  return new BandlabSDK({ bearerToken: 'My Bearer Token', baseURL: 'http://127.0.0.1:4010' });
}

/** Run `fn`, capture the URL of the first request, and answer it with a stub response. */
async function captureURL(fn: (c: BandlabSDK) => Promise<unknown>): Promise<string> {
  const calls: string[] = [];
  const realFetch = globalThis.fetch;
  globalThis.fetch = (async (input: any) => {
    calls.push(typeof input === 'string' ? input : input?.url ?? String(input));
    return new Response('{}', { status: 200, headers: { 'content-type': 'application/json' } });
  }) as typeof fetch;
  try {
    await fn(makeClient()).catch(() => undefined);
  } finally {
    globalThis.fetch = realFetch;
  }
  if (!calls.length) throw new Error('no request was issued');
  return calls[0]!;
}

describe('Authorizations paths match the APK evidence', () => {
  test('POST /authorizations hits /authorizations', async () => {
    const url = await captureURL((c) => c.authorizations.createSessionKey({}));
    expect(url).toContain('/authorizations');
  });

  test('GET /authorization/two-factor-methods hits /authorization/two-factor-methods', async () => {
    const url = await captureURL((c) => c.authorizations.listTwoFactorMethods({}));
    expect(url).toContain('/authorization/two-factor-methods');
  });

  test('POST /authorization/two-factor-requests/email hits /authorization/two-factor-requests/email', async () => {
    const url = await captureURL((c) => c.authorizations.createTwoFactorRequest({}));
    expect(url).toContain('/authorization/two-factor-requests/email');
  });

  test('POST /connect/token hits /connect/token', async () => {
    const url = await captureURL((c) => c.authorizations.createToken({}));
    expect(url).toContain('/connect/token');
  });

  test('GET /external/token hits /external/token', async () => {
    const url = await captureURL((c) => c.authorizations.retrieveExternalToken({}));
    expect(url).toContain('/external/token');
  });

  test('POST /logout hits /logout', async () => {
    const url = await captureURL((c) => c.authorizations.logout({}));
    expect(url).toContain('/logout');
  });
});
